    topic: 'technical', tag: 'دليل مواءمة',
    answer: 'مواءمة استخدام AI مع متطلبات الأمن تبدأ بتحديد الضوابط المنطبقة على الجهة والأصل والخدمة، ثم ربط كل ضابط بإجراء ومالك ودليل. لا توجد مواءمة صحيحة من مجرد إضافة شعار NCA أو قائمة أرقام إلى صفحة منتج، ولا يثبت هذا الدليل امتثالًا لجهة بعينها.',
    sections: [
      { title: 'ثبّت الوثيقة والنطاق أولًا', paragraphs: ['تعرض الهيئة الوطنية للأمن السيبراني الضوابط الأساسية ECC ومرجع الإصدار ECC 2-2024. راجع الوثيقة الحالية ونطاقها وما يرتبط بها من ضوابط قبل بناء مصفوفة الجهة. لا تفترض أن عنوان هذا المقال يعني انطباق كل ضابط على كل منشأة خاصة أو كل ميزة AI.', 'ارسم الأصول المتأثرة: واجهة المستخدم ونقطة التكامل وحساب المورد والمفاتيح والسجلات والأدوات المتصلة. قد يعمل النموذج لدى مورد، لكن صلاحيات التكامل وإدارة الحسابات والقرارات الداخلية تحتاج مسؤولية واضحة داخل المنشأة.'] },
      { title: 'اكتب مواءمة يمكن اختبارها', paragraphs: ['دوّن مرجع المتطلب بعد التحقق منه، وحدد الإجراء الذي يعالجه وحدود الإجراء. إذا كان الضابط يتعلق بالوصول، فاختبر مستخدمًا مسموحًا وآخر مرفوضًا وإلغاء الصلاحية، بدل الاكتفاء بصورة شاشة إعدادات.', 'الجدول التالي محاور تحضير عامة؛ لا ينقل نصوص الضوابط ولا يثبت المطابقة لأرقامها. يعتمد المختص المصفوفة الدقيقة من الوثائق الرسمية في نطاق الجهة.'], table: { headers: ['محور التحضير', 'سؤال في استخدام AI', 'دليل تقني مقترح'], rows: [['الأصول', 'هل نعرف الخدمات والتكاملات ومالكيها؟', 'جرد محدث وعلاقات موثقة'], ['الوصول', 'من يقرأ البيانات وينفذ الأدوات؟', 'صلاحيات واختبارات رفض وإلغاء'], ['المورد', 'ما حدود مسؤوليته والوصول للدعم؟', 'عقد ونطاق وإعداد متحقق'], ['الحوادث', 'كيف نعطل التكامل ونحفظ الدليل؟', 'إجراء وتمرين في بيئة مأذونة']] } },
      { title: 'لا تجعل سلامة النموذج بديلًا للأمن', paragraphs: ['حتى إن رفض النموذج بعض التعليمات الضارة، لا تمنحه أسرارًا أو صلاحيات لا يحتاجها. افصل المدخلات غير الموثوقة عن أوامر التنفيذ، وافرض الصلاحية في النظام الموثوق، واختبر ما يحدث إذا كانت إجابة النموذج غير صحيحة أو خرجت عن الصيغة المطلوبة.', 'قبل إغلاق أي فجوة، حدّد هل الدليل اختبار محلي أم نتيجة تشغيل أم مراجعة وثيقة فقط. لا تحول نجاح البناء أو فحص اتصال إلى تحقق أمني شامل. واربط تغيّر التكامل بإعادة فحص المواءمة بدل اعتبارها ملفًا يكتمل مرة واحدة.'] },
    ],
    example: 'مثال افتراضي: يستطيع مساعد داخلي استدعاء أداة تقرير. يجرب الفريق حسابًا بلا صلاحية، فيرفض الخادم الطلب حتى لو طلب النموذج تنفيذه. هذا دليل على حد وصول محدد، وليس شهادة بأن بقية النظام استوفى جميع ضوابط ECC.',
    checklist: ['تحقق من الوثيقة والنسخة ونطاق الانطباق.', 'اربط الأصل والضابط بالإجراء والمالك.', 'اختبر حالات الرفض وإلغاء الوصول والفشل.', 'صنّف الأدلة وحدودها قبل إعلان إغلاق الفجوة.'],
    faqs: [{ question: 'هل مواءمة ECC تعني اعتماد NCA للمنتج؟', answer: 'لا؛ المواءمة وصف لربط المتطلبات بالإجراءات والأدلة. لا تُعرض كشهادة أو اعتماد دون دليل مستقل يخص النطاق.' }, { question: 'هل حجب Prompt Injection يكفي للأمن؟', answer: 'لا. تبقى الصلاحيات والمفاتيح والبيانات والتكاملات والمورد والحوادث ضمن التقييم الأمني بحسب النطاق.' }],
